def get_cluster_cells_by_value(grid):
    """Get all connected components for each non-background non-3 color"""
    grid_rows, grid_cols = len(grid), len(grid[0])
    visited_cells = set()
    clusters = {}  # value -> list of lists of cells

    for r in range(grid_rows):
        for c in range(grid_cols):
            if grid[r][c] not in [0, 3] and (r, c) not in visited_cells:
                # BFS to get connected component
                color = grid[r][c]
                if color not in clusters:
                    clusters[color] = []
                component = []
                queue = [(r, c)]
                while queue:
                    rr, cc = queue.pop(0)
                    if (rr, cc) in visited_cells or grid[rr][cc] != color:
                        continue
                    visited_cells.add((rr, cc))
                    component.append((rr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nrr, ncc = rr + dr, cc + dc
                        if 0 <= nrr < grid_rows and 0 <= ncc < grid_cols:
                            if grid[nrr][ncc] == color and (nrr, ncc) not in visited_cells:
                                queue.append((nrr, ncc))
                clusters[color].append(component)

    return clusters

